#!/usr/bin/env bash
# Build the freestanding kernel.
#
#   Kernel/build.sh
#     -> Kernel/kernel.elf   image linked at 1 MiB (what a GRUB/UEFI loader takes)
#     -> Kernel/kernel.bin   the same image as flat bytes
#     -> Kernel/kernel.img   MBR + kernel.bin, boots as a raw hard disk
#
# The compiler emits assembly for Kernel/main.tl with no syscalls; the kernel
# runtime in Kernel/kruntime.s supplies print, the allocator, the diagnostics
# and the __k_* machine builtins at link time; Kernel/font8.s is the 8x8 text
# font (generated by Tools/make_font.py); Kernel/boot.s turns on long mode.
set -euo pipefail

root=$(cd "$(dirname "$0")/.." && pwd)
kernel="${root}/Kernel"
work=$(mktemp -d)
trap 'rm -rf "${work}"' EXIT

python3 "${root}/tcomp" build --freestanding --asm "${kernel}/main.tl" \
  > "${work}/main.s"
as --64 -mx86-used-note=no -o "${work}/main.o" "${work}/main.s"
as --64 -mx86-used-note=no -o "${work}/kruntime.o" "${kernel}/kruntime.s"
as --64 -mx86-used-note=no -o "${work}/font8.o" "${kernel}/font8.s"
as --64 -mx86-used-note=no -o "${work}/boot.o" "${kernel}/boot.s"
ld -z noseparate-code --build-id=none -T "${kernel}/kernel.ld" \
  -o "${kernel}/kernel.elf" "${work}/main.o" "${work}/kruntime.o" \
  "${work}/font8.o" "${work}/boot.o"
objcopy -O binary "${kernel}/kernel.elf" "${kernel}/kernel.bin"

# The MBR loads IMAGE_SECTORS sectors from Kernel/mbr.s, so that constant is
# the single source of truth for the window and this script reads it instead of
# repeating it.  The image is copied to 0x7e00, and the MBR keeps the VBE
# mode-info block at 0x1FE00 and the boot-info block at 0x1FF00, so the image
# must end at or below 0x1FE00.
sectors=$(sed -n 's/^\.set[[:space:]]*IMAGE_SECTORS,[[:space:]]*\([0-9]\+\).*/\1/p' "${kernel}/mbr.s")
if [ -z "${sectors}" ]; then
  echo "could not read IMAGE_SECTORS from Kernel/mbr.s" >&2
  exit 1
fi
image_bytes=$(( sectors * 512 ))
load_end=$(( 0x7e00 + image_bytes ))
kernel_bytes=$(wc -c < "${kernel}/kernel.bin")
if [ "${kernel_bytes}" -gt "${image_bytes}" ]; then
  echo "kernel.bin is ${kernel_bytes} bytes; the MBR loads ${image_bytes}" >&2
  exit 1
fi
if [ "${load_end}" -gt $(( 0x1fe00 )) ]; then
  echo "the image would end at ${load_end}; 0x1fe00 holds the mode-info block" >&2
  exit 1
fi

as --32 -mx86-used-note=no -o "${work}/mbr.o" "${kernel}/mbr.s"
ld -m elf_i386 -e _mbr -Ttext 0x7c00 -z max-page-size=1 --oformat binary \
  -o "${work}/mbr.bin" "${work}/mbr.o"
dd if="${work}/mbr.bin" of="${work}/mbr512" bs=512 count=1 status=none

dd if="${work}/mbr512" of="${kernel}/kernel.img" bs=512 count=1 status=none
dd if=/dev/zero of="${kernel}/kernel.img" bs=512 seek=1 count=${sectors} \
  conv=notrunc status=none
dd if="${kernel}/kernel.bin" of="${kernel}/kernel.img" bs=512 seek=1 \
  conv=notrunc status=none

echo "Kernel/kernel.elf ($(wc -c < "${kernel}/kernel.elf") bytes)"
echo "Kernel/kernel.bin ($(wc -c < "${kernel}/kernel.bin") bytes)"
echo "Kernel/kernel.img ($(wc -c < "${kernel}/kernel.img") bytes)"
